import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

// Local shapes for the fields this scenario reads. They follow openapi.json.
interface VendorOut {
  id: string;
  status: string;
}

interface DocumentOut {
  id: string;
  vendor_id: string;
  kind: "w9" | "insurance_certificate" | "contract";
  status: "processing" | "extracted" | "failed";
  created_at: string;
}

interface ExtractionOut {
  id: string;
  document_id: string;
  kind: string;
  fields: Record<string, { value: string | null; confidence: number }>;
  status: string;
}

interface ReviewQueueItem {
  vendor_id: string;
  extractions: ExtractionOut[];
}

// Unique per run, so parallel tests never collide on names or emails.
const unique = () => `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

/** Polls a document until extraction has finished, then returns the document. */
async function waitForExtracted(api: APIRequestContext, documentId: string): Promise<DocumentOut> {
  let doc = await expectStatus<DocumentOut>(await api.get(`/api/documents/${documentId}`), 200);
  for (let i = 0; i < 40 && doc.status === "processing"; i++) {
    await new Promise((resolve) => setTimeout(resolve, 250));
    doc = await expectStatus<DocumentOut>(await api.get(`/api/documents/${documentId}`), 200);
  }
  expect(doc.status).toBe("extracted");
  return doc;
}

/**
 * Uploads a document whose content carries the legal name. The extractor is assumed to read
 * "Legal name: <name>" from the file body and expose it as the `legal_name` field.
 */
async function upload(
  api: APIRequestContext,
  vendorId: string,
  kind: DocumentOut["kind"],
  legalName?: string,
): Promise<DocumentOut> {
  const body = legalName ? `Legal name: ${legalName}\n` : `Placeholder ${kind}\n`;
  const response = await api.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: {
        name: `${kind}-${unique()}.txt`,
        mimeType: "text/plain",
        buffer: Buffer.from(body),
      },
    },
  });
  const created = await expectStatus<DocumentOut>(response, 201);
  return waitForExtracted(api, created.id);
}

test.describe("vendor lifecycle", () => {
  test(
    "a re-uploaded document is the one that gets reviewed",
    { tag: "@LIF-01" },
    async ({ apiAs }) => {
      // Arrange: a member creates a draft vendor with its insurance and contract documents.
      const member = await apiAs("member");
      const vendor = await expectStatus<VendorOut>(
        await member.post("/api/vendors", {
          data: {
            name: `Lifecycle Vendor ${unique()}`,
            category: "services",
            contact_email: `lifecycle-${unique()}@northwind.test`,
          },
        }),
        201,
      );
      expect(vendor.status).toBe("draft");

      await upload(member, vendor.id, "insurance_certificate");
      await upload(member, vendor.id, "contract");

      // Arrange: two w9 uploads, each with a different legal name; the second is the re-upload.
      const firstW9 = await upload(member, vendor.id, "w9", "First Name LLC");
      const secondW9 = await upload(member, vendor.id, "w9", "Second Name LLC");

      // Act: submit the vendor.
      const submitted = await expectStatus<VendorOut>(
        await member.post(`/api/vendors/${vendor.id}/submit`),
        200,
      );
      expect(submitted.status).toBe("in_review");

      // Act: a reviewer opens the queue.
      const reviewer = await apiAs("reviewer");
      const queue = await expectStatus<ReviewQueueItem[]>(await reviewer.get("/api/review-queue"), 200);
      const item = queue.find((entry) => entry.vendor_id === vendor.id);
      expect(item, "submitted vendor should appear in the review queue").toBeDefined();

      // Assert: the vendor's w9 extraction in the queue carries the second upload's legal name.
      const w9Extractions = item!.extractions.filter((e) => e.kind === "w9");
      expect(w9Extractions).toHaveLength(1);
      expect(w9Extractions[0].document_id).toBe(secondW9.id);
      expect(w9Extractions[0].fields.legal_name?.value).toBe("Second Name LLC");

      // Assert: the documents list shows both w9 uploads, oldest first.
      const documents = await expectStatus<DocumentOut[]>(
        await member.get(`/api/vendors/${vendor.id}/documents`),
        200,
      );
      const w9s = documents.filter((d) => d.kind === "w9");
      expect(w9s.map((d) => d.id)).toEqual([firstW9.id, secondW9.id]);
      expect(Date.parse(w9s[0].created_at)).toBeLessThanOrEqual(Date.parse(w9s[1].created_at));
    },
  );
});
